function not(x){ return x===V.T?V.F : x===V.F?V.T : V.U }
function or(a,b){ return a===V.T||b===V.T?V.T : (a===V.U||b===V.U?V.U : V.F) }
function and(a,b){ return a===V.F||b===V.F?V.F : (a===V.T && b===V.T ? V.T : V.U) }
